import{_ as s,l,o as e,c as o,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"TLS 握手","description":"","frontmatter":{"title":"TLS 握手","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tls-handshake.md","filePath":"cs/tls-handshake.md","lastUpdated":1789023840000}'),c={name:"cs/tls-handshake.md"};function A(E,a,T,_,S,f){const i=l("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="tls-握手" tabindex="-1">TLS 握手 <a class="header-anchor" href="#tls-握手" aria-label="Permalink to &quot;TLS 握手&quot;">​</a></h1><div class="epigraph"><p>握手一次性做完：协商版本与套件、用证书认证服务器、派生会话键，随后记录层用 AEAD 保护字节。</p><footer>—— RFC 8446, The Transport Layer Security (TLS) Protocol Version 1.3</footer></div><p><a href="/cs/transient-exec">上一课</a>把微结构泄漏标进模型。本课不谈缓存。网络课已有<a href="/cs/http-tls-entry">TLS 入口</a>：HTTPS 在 HTTP 下加一条保密管道。缺口是：握手如何把<a href="/cs/pubkey-envelope">公钥信封</a>、<a href="/cs/cert-pki">证书</a>、<a href="/cs/symmetric-crypto">AEAD</a>装成一次协议，使后续套接字字节带 CIA 的 C 与 I。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只「开始加密」不够：要防降级、要认证名字、要前向保密、要 Finished 绑定。TLS 1.3 把密钥交换收成 ECDHE（或 PSK），证书在加密之后发，减少明文元数据。缺口不是重讲 TCP 三次握手，而是记录层与握手消息的分工：明文只留下为了把会话建起来所必需的那几项。</p><p><span class="marginnote">1.3 去掉了大量历史套件与 RSA 静态密钥交换，正是为了关掉「没有前向保密」与「加密但不认证」的组合。旧版本对照见网络课入口，本课以 1.3 为机制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ClientHello / ServerHello 协商群与密钥份额；双方派生握手密钥与应用密钥。服务器出示证书链，用私钥证明；客户端核验证书与主机名。Finished 用 MAC 绑全部握手字节，防改套件。之后应用数据走 AEAD。本课不写报文字段表当实现抄本。</p>',8)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HELLO%5B%22Hello%3A%20%E5%AF%86%E9%92%A5%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20CERT%5B%22%E8%AF%81%E4%B9%A6%E8%AE%A4%E8%AF%81%22%5D%0A%20%20CERT%20--%3E%20FIN%5B%22Finished%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20FIN%20--%3E%20AEAD%5B%22%E8%AE%B0%E5%BD%95%E5%B1%82%20AEAD%22%5D%0A%20%20AEAD%20--%3E%20FW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E9%98%B2%E7%81%AB%E5%A2%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>握手服务真实性 + 密钥协商；记录层服务保密与完整。这把认证协议课的「绑到会话键」做成互联网默认实例。中间盒子若要看见明文，必须成为端点（终止 TLS），从而进入另一威胁模型——后课中间人。0-RTT 用 PSK 提前发数据，有重放窗口，是可用性与安全的挤法，本课只点名。</p><p>证书在 1.3 里于加密后出示，减少明文元数据，不减少必须验链这一步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TLS 不保护端点内存、不保护 DNS 若未另行认证、不保护证书误签。也不把 QUIC 的加密运输再推一遍——<a href="/cs/quic-contrast">QUIC 对照</a>已在网络课。防火墙看到的往往是已加密的流，下一课只能按连接状态而不是按 URL 过滤。</p><p>会话票与 PSK 恢复必须当密钥材料保护，否则握手再短也把长期秘密拉长暴露面。后课默认：链路在 1.3 记录层下有会话键；边界设备面对的是五元组与状态，不是明文 HTTP。</p><p>握手本身也是 DoS 面：公钥运算贵。后课可用轴会回到这里；本课先把正确协商钉死。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>Finished 把握手字节绑进密钥，防改套件与降级。</p></li><li><p>后课防火墙在加密流上只能看见五元组与状态。</p></li><li><p>入口课有管道；本课把 1.3 握手收成协商、证书、Finished、AEAD。</p></li><li><p>前向保密来自临时 DH；认证来自 PKI 名字绑定。</p></li><li><p>加密后过滤只能靠连接状态，是防火墙课缺口。</p></li><li><p>出处：RFC 8446；对照 Diffie–Hellman 与 AEAD 先修。</p></li></ul>',9))])}const D=s(c,[["render",A]]);export{u as __pageData,D as default};
